const now = new Date();
const until = new Date(now);
const since = new Date(now);
since.setDate(since.getDate() - 7);

const githubRepo = ($vars.GITHUB_REPO || '').trim();
const language = (($vars.SUMMARY_LANGUAGE || 'EN').trim().toUpperCase() === 'FR') ? 'FR' : 'EN';

if (!githubRepo || !githubRepo.includes('/')) {
  throw new Error('Set n8n variable GITHUB_REPO to owner/repository.');
}
if (!$vars.GITHUB_TOKEN) {
  throw new Error('Set n8n variable GITHUB_TOKEN to a token with public_repo or repo read access.');
}
if (!$vars.ANTHROPIC_API_KEY) {
  throw new Error('Set n8n variable ANTHROPIC_API_KEY.');
}
if (!$vars.DESTINATION_WEBHOOK_URL) {
  throw new Error('Set n8n variable DESTINATION_WEBHOOK_URL to a Discord webhook URL.');
}

return [{
  json: {
    githubRepo,
    githubToken: $vars.GITHUB_TOKEN,
    anthropicApiKey: $vars.ANTHROPIC_API_KEY,
    destinationWebhookUrl: $vars.DESTINATION_WEBHOOK_URL,
    language,
    weekStartIso: since.toISOString(),
    weekEndIso: until.toISOString(),
    weekStartDate: since.toISOString().slice(0, 10),
    weekEndDate: until.toISOString().slice(0, 10)
  }
}];

const cfg = $items('Build Weekly Window')[0].json;

function nodeItems(name) {
  try {
    return $items(name).map((item) => item.json);
  } catch (error) {
    return [];
  }
}

function flatten(items) {
  if (items.length === 1 && Array.isArray(items[0])) {
    return items[0];
  }
  return items;
}

const commits = flatten(nodeItems('Fetch Commits'))
  .map((commit) => ({
    sha: String(commit.sha || '').slice(0, 7),
    message: commit.commit?.message || commit.message || '',
    author: commit.commit?.author?.name || commit.author?.login || 'Unknown',
    url: commit.html_url || commit.url || ''
  }))
  .filter((commit) => commit.message)
  .slice(0, 40);

const closedIssuesResponse = nodeItems('Fetch Closed Issues')[0] || {};
const closedIssues = (closedIssuesResponse.items || flatten(nodeItems('Fetch Closed Issues')))
  .map((issue) => ({
    number: issue.number,
    title: issue.title,
    closedAt: issue.closed_at,
    url: issue.html_url
  }))
  .filter((issue) => issue.title)
  .slice(0, 40);

const mergedPrsResponse = nodeItems('Fetch Merged Pull Requests')[0] || {};
const mergedPullRequests = (mergedPrsResponse.items || flatten(nodeItems('Fetch Merged Pull Requests')))
  .map((pullRequest) => ({
    number: pullRequest.number,
    title: pullRequest.title,
    mergedAt: pullRequest.closed_at,
    author: pullRequest.user?.login || 'Unknown',
    url: pullRequest.html_url
  }))
  .filter((pullRequest) => pullRequest.title)
  .slice(0, 40);

const languageName = cfg.language === 'FR' ? 'French' : 'English';
const activity = {
  repository: cfg.githubRepo,
  period: `${cfg.weekStartDate} to ${cfg.weekEndDate}`,
  totals: {
    commits: commits.length,
    closedIssues: closedIssues.length,
    mergedPullRequests: mergedPullRequests.length
  },
  commits,
  closedIssues,
  mergedPullRequests
};

const prompt = `Write a concise weekly development narrative in ${languageName}.\n\nUse the supplied GitHub activity JSON. Summarize the week for engineers and product stakeholders. Include:\n1. One short opening paragraph.\n2. Key highlights.\n3. Risks or follow-ups if they are visible from the data.\n4. A compact metrics line.\n\nAvoid inventing work that is not present in the JSON.\n\nActivity JSON:\n${JSON.stringify(activity, null, 2)}`;

return [{
  json: {
    ...cfg,
    activity,
    claudeRequest: {
      model: 'claude-sonnet-4-20250514',
      max_tokens: 1200,
      system: 'You write accurate weekly engineering summaries from GitHub activity data. Do not invent facts.',
      messages: [
        {
          role: 'user',
          content: prompt
        }
      ]
    }
  }
}];

const cfg = $items('Build Weekly Window')[0].json;
const response = $items('Claude Narrative Summary')[0].json;
const content = Array.isArray(response.content)
  ? response.content.map((part) => part.text || '').filter(Boolean).join('\n\n')
  : (response.text || JSON.stringify(response));

const heading = `Weekly dev summary for ${cfg.githubRepo}`;
let message = `**${heading}**\n${content}`;
if (message.length > 1900) {
  message = `${message.slice(0, 1875)}\n\n...summary truncated for Discord.`;
}

return [{
  json: {
    githubRepo: cfg.githubRepo,
    language: cfg.language,
    summary: content,
    discordPayload: {
      content: message
    }
  }
}];
